const data = items.map(item => item.json);

const summary = {
  total: data.length,
  hot: data.filter(i => i.Category === "Hot").length,
  warm: data.filter(i => i.Category === "Warm").length,
  cold: data.filter(i => i.Category === "Cold").length,
};

// Optional: leads added today
const today = new Date().toLocaleDateString('en-US');
summary.today = data.filter(i => i.Date === today).length;

return [{ json: summary }];

// 🧠 Smart CRM AI Report Parser (JSON-based Version)
// Handles outputs where the AI wraps valid JSON in markdown code blocks

// Step 1️⃣: Extract raw output from AI node
let rawOutput = $json["output"] || ($json[0] && $json[0].output) || "";
if (!rawOutput) {
  return [{ json: { error: "No AI output received." } }];
}

// Step 2️⃣: Remove markdown fences and clean whitespace
let cleanText = rawOutput
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

// Step 3️⃣: Try parsing as JSON
let parsed;
try {
  parsed = JSON.parse(cleanText);
} catch (err) {
  return [{ json: { error: "Failed to parse JSON from AI output", rawOutput: cleanText } }];
}

// Step 4️⃣: Normalize key naming (for consistency with your email template)
const result = {
  dateRange: parsed.dateRange || "",
  newLeads: parsed.newLeads || 0,
  totalLeads: parsed.totalLeads || 0,
  hotLeads: parsed.hotLeads || 0,
  warmLeads: parsed.warmLeads || 0,
  coldLeads: parsed.coldLeads || 0,
  totalChange: parsed.totalChange || "0",
  hotChange: parsed.hotChange || "0",
  warmChange: parsed.warmChange || "0",
  coldChange: parsed.coldChange || "0",
  hotPercent: parsed.hotPercent || 0,
  insight1: parsed.insight1 || "",
  insight2: parsed.insight2 || "",
  insight3: parsed.insight3 || "",
  recommendation1: parsed.recommendation1 || "",
  recommendation2: parsed.recommendation2 || "",
  recommendation3: parsed.recommendation3 || "",
  aiCommentary: parsed.aiCommentary || "",
};

// Step 5️⃣: Return structured data for HTML or email nodes
return [{ json: result }];

